/** Alle Karten als flache Liste { id, topic, q, a, x:[falsch…], e } */
export const CARDS = Object.entries(RAW).flatMap(([topic, list]) =>
  list.map((row, i) => row && { id: `${topic}-${String(i + 1).padStart(2, "0")}`, topic, year: row[0], q: row[1], a: row[2], x: row[3], e: row[4] || "" }).filter(Boolean));

export const topicOf = (id) => TOPICS.find((t) => t.id === id) || null;

